<script setup lang="ts">import { ChevronLeft, ChevronRight } from '@lucide/vue'; withDefaults(defineProps<{ page: number; lastPage?: number; total: number; perPage?: number }>(), { lastPage: 1, perPage: 20 }); const emit = defineEmits<{ change: [page: number] }>()</script>
<template><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><p class="text-sm text-[#60728a]">Showing {{ total ? ((page - 1) * perPage) + 1 : 0 }}–{{ Math.min(page * perPage, total) }} of {{ total }}</p><div class="flex items-center gap-2"><button class="pressable rounded-lg border border-[#cbd8e7] bg-white p-2 text-[#51657d] hover:bg-[#edf3f9] disabled:opacity-40" :disabled="page <= 1" aria-label="Previous page" @click="emit('change', page - 1)"><ChevronLeft class="size-4" /></button><span class="px-2 py-2 text-sm tabular-nums text-[#51657d]">Page {{ page }} of {{ lastPage }}</span><button class="pressable rounded-lg border border-[#cbd8e7] bg-white p-2 text-[#51657d] hover:bg-[#edf3f9] disabled:opacity-40" :disabled="page >= lastPage" aria-label="Next page" @click="emit('change', page + 1)"><ChevronRight class="size-4" /></button></div></div></template>
